-- Records of QRTZ_SIMPROP_TRIGGERS
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for QRTZ_TRIGGERS
-- ----------------------------
DROP TABLE IF EXISTS `QRTZ_TRIGGERS`;
CREATE TABLE `QRTZ_TRIGGERS` (
  `sched_name` varchar(120) NOT NULL COMMENT '调度名称',
  `trigger_name` varchar(200) NOT NULL COMMENT '触发器的名字',
  `trigger_group` varchar(200) NOT NULL COMMENT '触发器所属组的名字',
  `job_name` varchar(200) NOT NULL COMMENT 'qrtz_job_details表job_name的外键',
  `job_group` varchar(200) NOT NULL COMMENT 'qrtz_job_details表job_group的外键',
  `description` varchar(250) DEFAULT NULL COMMENT '相关介绍',
  `next_fire_time` bigint DEFAULT NULL COMMENT '上一次触发时间（毫秒）',
  `prev_fire_time` bigint DEFAULT NULL COMMENT '下一次触发时间（默认为-1表示不触发）',
  `priority` int DEFAULT NULL COMMENT '优先级',
  `trigger_state` varchar(16) NOT NULL COMMENT '触发器状态',
  `trigger_type` varchar(8) NOT NULL COMMENT '触发器的类型',
  `start_time` bigint NOT NULL COMMENT '开始时间',
  `end_time` bigint DEFAULT NULL COMMENT '结束时间',
  `calendar_name` varchar(200) DEFAULT NULL COMMENT '日程表名称',
  `misfire_instr` smallint DEFAULT NULL COMMENT '补偿执行的策略',
  `job_data` blob COMMENT '存放持久化job对象',
  PRIMARY KEY (`sched_name`,`trigger_name`,`trigger_group`),
  KEY `sched_name` (`sched_name`,`job_name`,`job_group`),
  CONSTRAINT `qrtz_triggers_ibfk_1` FOREIGN KEY (`sched_name`, `job_name`, `job_group`) REFERENCES `QRTZ_JOB_DETAILS` (`sched_name`, `job_name`, `job_group`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='触发器详细信息表';

-- ----------------------------
-- Records of QRTZ_TRIGGERS
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for quality_fixes
-- ----------------------------
DROP TABLE IF EXISTS `quality_fixes`;
CREATE TABLE `quality_fixes` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '修复ID',
  `issue_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题ID',
  `fix_description` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '修复描述',
  `images` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '修复图片JSON',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '修复状态',
  `fixed_by` bigint NOT NULL COMMENT '修复人ID（sys_user.user_id）',
  `fixed_at` datetime DEFAULT NULL COMMENT '修复时间',
  `verified_by` bigint DEFAULT NULL COMMENT '验收人ID（sys_user.user_id）',
  `verified_at` datetime DEFAULT NULL COMMENT '验收时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_issue_id` (`issue_id`),
  KEY `idx_status` (`status`),
  KEY `idx_fixed_by` (`fixed_by`),
  KEY `idx_fixed_at` (`fixed_at`),
  KEY `fk_fix_verifier` (`verified_by`),
  CONSTRAINT `fk_fix_issue` FOREIGN KEY (`issue_id`) REFERENCES `quality_issues` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_fix_user` FOREIGN KEY (`fixed_by`) REFERENCES `sys_user` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_fix_verifier` FOREIGN KEY (`verified_by`) REFERENCES `sys_user` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='问题修复表';

-- ----------------------------
-- Records of quality_fixes
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for quality_inspections
-- ----------------------------
DROP TABLE IF EXISTS `quality_inspections`;
CREATE TABLE `quality_inspections` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '质检ID',
  `project_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目ID',
  `schedule_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联进度ID',
  `inspection_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '质检类型',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '质检标题',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '质检描述',
  `result` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '质检结果',
  `inspector_id` bigint NOT NULL COMMENT '检查员ID（sys_user.user_id）',
  `inspection_date` datetime DEFAULT NULL COMMENT '检查日期',
  `images` text COLLATE utf8mb4_unicode_ci COMMENT '质检图片JSON',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_schedule_id` (`schedule_id`),
  KEY `idx_result` (`result`),
  KEY `idx_inspector_id` (`inspector_id`),
  KEY `idx_inspection_date` (`inspection_date`),
  CONSTRAINT `fk_qi_inspector` FOREIGN KEY (`inspector_id`) REFERENCES `sys_user` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_qi_project` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_qi_schedule` FOREIGN KEY (`schedule_id`) REFERENCES `project_schedules` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='质检表';

-- ----------------------------
-- Records of quality_inspections
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for quality_issues
-- ----------------------------
DROP TABLE IF EXISTS `quality_issues`;
CREATE TABLE `quality_issues` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题ID',
  `inspection_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '质检ID',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题标题',
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题描述',
  `severity` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM' COMMENT '严重程度',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题分类',
  `location` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '问题位置',
  `images` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题图片JSON',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OPEN' COMMENT '问题状态',
  `reported_by` bigint NOT NULL COMMENT '上报人ID（sys_user.user_id）',
  `reported_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上报时间',
  `resolved_by` bigint DEFAULT NULL COMMENT '解决人ID（sys_user.user_id）',
  `resolved_at` datetime DEFAULT NULL COMMENT '解决时间',
  `due_date` datetime DEFAULT NULL COMMENT '整改期限',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_inspection_id` (`inspection_id`),
  KEY `idx_severity` (`severity`),
  KEY `idx_status` (`status`),
  KEY `idx_reported_by` (`reported_by`),
  KEY `idx_due_date` (`due_date`),
  KEY `fk_issue_resolver` (`resolved_by`),
  CONSTRAINT `fk_issue_inspection` FOREIGN KEY (`inspection_id`) REFERENCES `quality_inspections` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_issue_reporter` FOREIGN KEY (`reported_by`) REFERENCES `sys_user` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_issue_resolver` FOREIGN KEY (`resolved_by`) REFERENCES `sys_user` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='质量问题表';

-- ----------------------------
-- Records of quality_issues
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for schedule_records
-- ----------------------------
DROP TABLE IF EXISTS `schedule_records`;
CREATE TABLE `schedule_records` (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '记录ID',
  `schedule_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '进度ID',
  `record_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '记录类型（START:开始、PROGRESS:进度更新、COMPLETE:完成、ISSUE:问题）',
  `completion_rate` decimal(5,2) DEFAULT NULL COMMENT '完成度百分比',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '记录描述',
  `images` text COLLATE utf8mb4_unicode_ci COMMENT '现场图片JSON',
  `recorded_by` bigint NOT NULL COMMENT '记录人（sys_user.user_id）',
  `recorded_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录时间',
  PRIMARY KEY (`id`),
  KEY `idx_schedule_id` (`schedule_id`),
  KEY `idx_record_type` (`record_type`),
  KEY `idx_recorded_by` (`recorded_by`),
  KEY `idx_recorded_at` (`recorded_at`),
  CONSTRAINT `fk_record_schedule` FOREIGN KEY (`schedule_id`) REFERENCES `project_schedules` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_record_user` FOREIGN KEY (`recorded_by`) REFERENCES `sys_user` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='进度记录表';

-- ----------------------------
-- Records of schedule_records
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_config`;
CREATE TABLE `sys_config` (
  `config_id` int NOT NULL AUTO_INCREMENT COMMENT '参数主键',
  `config_name` varchar(100) DEFAULT '' COMMENT '参数名称',
  `config_key` varchar(100) DEFAULT '' COMMENT '参数键名',
  `config_value` varchar(500) DEFAULT '' COMMENT '参数键值',
  `config_type` char(1) DEFAULT 'N' COMMENT '系统内置（Y是 N否）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`config_id`)
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='参数配置表';

-- ----------------------------
-- Records of sys_config
-- ----------------------------
BEGIN;
